SELECT analytics_order_facts.customer_segment, SUM(analytics_order_facts.contribution_margin) / CAST(NULLIF(SUM(analytics_order_facts.net_revenue), 0) AS DECIMAL) AS contribution_margin_pct FROM analytics_order_facts WHERE analytics_order_facts.year = 2023 AND analytics_order_facts.month = 11 AND analytics_order_facts.region = 'East' AND analytics_order_facts.channel = 'marketplace' AND analytics_order_facts.category = 'category_04' GROUP BY analytics_order_facts.customer_segment ORDER BY contribution_margin_pct DESC, analytics_order_facts.customer_segment ASC LIMIT 12
